from pathlib import Path
import subprocess,os,json,re
E=Path(__file__).resolve().parent
env=dict(os.environ,GOTOOLCHAIN='go1.25.11',GOWORK='off')
rows=json.loads((E/'diagnostics.json').read_text());out={}
for row in rows:
 label=row['label'];version=row['server'];kinds=['cpu','mutex','block'] if row['diagnostic']=='cpu' else ['sched','sync']
 out[label]={}
 for kind in kinds:
  args=['go','tool','pprof','-raw',str(E/(version+'-probe')),str(E/(label+'.'+kind))]
  raw=subprocess.check_output(args,env=env,text=True);(E/(label+'-'+kind+'-raw.txt')).write_text(raw)
  samples,locations=raw.split('Locations\n',1)
  locations=locations.split('Mappings\n',1)[0]
  mapping={};current=None
  for line in locations.splitlines():
   m=re.match(r'\s*(\d+): (.*)',line)
   if m:current=int(m[1]);mapping[current]=m[2]
   elif current is not None:mapping[current]+=' '+line
  groups={name:{'count':0,'nanoseconds':0} for name in ['total','executor_wakeup','service_enqueue','queue_timer']}
  for line in samples.splitlines():
   m=re.fullmatch(r'\s*(\d+)\s+(\d+):((?:\s+\d+)+)\s*',line)
   if not m:continue
   count,ns=int(m[1]),int(m[2]);stack='\n'.join(mapping[int(i)] for i in m[3].split())
   names=['total']
   if 'rpc.(*Executor).Submit' in stack:names.append('executor_wakeup')
   if 'rpc.(*Service).Enqueue' in stack or 'rpc.(*Service).enqueue' in stack:names.append('service_enqueue')
   if 'rpc.(*Service).armQueueTimerLocked' in stack:names.append('queue_timer')
   for name in names:groups[name]['count']+=count;groups[name]['nanoseconds']+=ns
  assert groups['total']['count']>0,(label,kind)
  for g in groups.values():
   g['microseconds_per_event']=g['nanoseconds']/g['count']/1000 if g['count'] else None
   g['percent_total_time']=g['nanoseconds']/groups['total']['nanoseconds']*100
  out[label][kind]=groups
(E/'profile-summary.json').write_text(json.dumps(out,indent=2)+'\n')
print(json.dumps({label:{kind:v['executor_wakeup'] if kind=='sched' else v['service_enqueue'] for kind,v in kinds.items()} for label,kinds in out.items()},indent=2))

